fn usage(name:&CStr){unsafe{printf(c!("%s [--help|-?] [-f <facility_name>] [-k <redirect_kmsg>] [-n <detect_hungup>]\n--help            \tShow usage\n-f <facility_name>\tUse <facility_name> when redirecting kmsg by using syslog()\n-k <redirect_kmsg>\t1: Redirect kmsg\n                  \t0: Otherwise\n-i <monitor_interval>\t!=-1: Polling interval (in second) for detecting hungup\n                  \t-1: Don't detect hungup\n"),name.as_ptr());}}
fn parse_interval(value: &CStr) -> Option<i32> {
 // Keep the existing signed interval domain, including -1 (disabled). Require
 // a complete decimal conversion so malformed/overflow input cannot select 0/-1.
 unsafe extern "C" {
  fn strtol(value: *const c_char, end: *mut *mut c_char, base: c_int) -> std::os::raw::c_long;
  fn __errno_location() -> *mut c_int;
 }
 let mut end = std::ptr::null_mut();
 // SAFETY: CStr provides a live terminated input; end is writable storage.
 // strtol returns end within that input, including its terminating NUL.
 let (number, error) = unsafe {
  *__errno_location() = 0;
  let number = strtol(value.as_ptr(), &mut end, 10);
  (number, *__errno_location())
 };
 if error != 0 || end == value.as_ptr() as *mut c_char || unsafe { *end } != 0 {
  return None;
 }
 i32::try_from(number).ok()
}
